+)

 import (
 	"context"
@@ -53,6 +57,11 @@ func (a *artwork) Get(ctx context.Context, id string, size int) (reader io.ReadC
 			log.Error(ctx, "Error accessing image cache", "id", id, "size", size, err)
 		}
 		return nil, time.Time{}, err
+if errors.Is(err, cache.ErrNotFound) {
+			r, err = newPlaceholderReader()
