@@ -109,3 +118,15 @@ func (a *artwork) getArtworkReader(ctx context.Context, artID model.ArtworkID, s
 	}
 	return artReader, err
 }
+func newPlaceholderReader() (io.ReadCloser, error) {
+	f, err := os.Open("resources/placeholder.png")
+	if err != nil {
+		return nil, err
+	}
+	buf := new(bytes.Buffer)
+	if _, err := io.Copy(buf, f);
+	err != nil {
+		return nil, err
+	}
+	return io.NopCloser(bytes.NewReader(buf.Bytes())), nil
+}
